installer-gui-script.script:
// Runs in Installer.app as the logged-in user, before authentication —
// so system.env.HOME is the right home to probe.
function home() {
  return system.env.HOME || ('/Users/' + system.env.USER);
}
function anyPath(paths) {
  for (var i = 0; i < paths.length; i++) {
    if (system.files.fileExistsAtPath(paths[i])) return true;
  }
  return false;
}
function hasClaudeCode() {
  return anyPath([
    home() + '/.claude',
    home() + '/.claude/local/claude',
    home() + '/.local/bin/claude',
    '/opt/homebrew/bin/claude',
    '/usr/local/bin/claude'
  ]);
}
function hasCodex() {
  return anyPath([
    home() + '/.codex',
    home() + '/.local/bin/codex',
    '/opt/homebrew/bin/codex',
    '/usr/local/bin/codex'
  ]);
}
function hasOpencode() {
  return anyPath([home() + '/.config/opencode', home() + '/.opencode']);
}
function hasPi() {
  // pi's agent dir (models.json, extensions/); the npm-installed CLI
  // lands in one of the usual bin dirs.
  return anyPath([
    home() + '/.pi/agent',
    home() + '/.local/bin/pi',
    '/opt/homebrew/bin/pi',
    '/usr/local/bin/pi'
  ]);
}
function hasDesktop() {
  return anyPath(['/Applications/Claude.app', home() + '/Applications/Claude.app']);
}
function installCheck() {
  // Only an arm64 binary is published (release.yml).
  if (system.sysctl('hw.optional.arm64') != '1') {
    my.result.title = 'Apple silicon required';
    my.result.message = 'This build of parsec runs on Apple silicon Macs only.';
    my.result.type = 'Fatal';
    return false;
  }
  return true;
}
